def edits_for(path):
    return EDITS


def targets(a):
    out = [] if a.only_kiosk else [Path(a.root) / 'desktop' / 'renderer' / 'script-page.js']
    if a.kiosk:
        out.append(Path(a.kiosk))
    return out


if __name__ == "__main__":
    sys.exit(run(targets, edits_for))
